+					  LAN86XX_REG_IMSK1, mask);
 	}
 
 	ret = phy_set_bits_mmd(phydev, MDIO_MMD_VEND2, LAN86XX_REG_IMSK1,
-			       LAN86XX_STS1_PLCA_STS_CHANGED);
+			       mask);
 	if (ret)
